def test_codex_cli_structured_validation_retry_records_fallback(monkeypatch):
    events = []
    calls = []

    class TinyModel(codex_cli.BaseModel):
        name: str
        score: float

    responses = iter(['{"name":"ABC"}', '{"name":"ABC","score":0.7}'])

