        failure_stage="ad_hoc_parse",
        error=ValueError("Could not find Screener.in results table tokenId=SECRET123"),
        screener_url="https://www.screener.in/screen/raw/?query=Current+price+%3E+DMA+50&tokenId=SECRET123",
